-- 036 · Mindset (refonte de Shaï, nov. 2026)
-- Uniquement des ajouts : les valeurs déjà autorisées restent valides.

-- 1. Journal : le « bilan du soir » et les pages de parcours, nouvelles humeurs.
--    Les contraintes sont ÉLARGIES (anciennes valeurs conservées).
alter table public.mindset_entries drop constraint if exists mindset_entries_kind_check;
alter table public.mindset_entries add constraint mindset_entries_kind_check
  check (kind = any (array['intention','journal','meditation_done','affirmation_seen','breathing_done','bilan_du_soir','parcours']));
alter table public.mindset_entries drop constraint if exists mindset_entries_mood_check;
alter table public.mindset_entries add constraint mindset_entries_mood_check
  check (mood = any (array['great','good','neutral','tired','low','calm','light','tense','energized','lost']));

-- Jour du parcours auquel se rattache une page (kind = 'parcours').
alter table public.mindset_entries add column if not exists program_day integer;
create index if not exists mindset_entries_user_created_idx on public.mindset_entries (user_id, created_at desc);

-- 2. Catalogue de rituels : trois gestes des maquettes qui manquaient.

insert into public.mindset_ritual_catalog (label, icon, sort_order, i18n)
  select $q$Un soin rien que pour moi$q$, 'heart', 11, $q${"en": {"label": "A treat just for me"}, "he": {"label": "טיפוח רק בשבילי"}, "es": {"label": "Un cuidado solo para mí"}, "ru": {"label": "Забота только для себя"}}$q$::jsonb
  where not exists (select 1 from public.mindset_ritual_catalog where label = $q$Un soin rien que pour moi$q$);

insert into public.mindset_ritual_catalog (label, icon, sort_order, i18n)
  select $q$Cinq respirations lentes$q$, 'wind', 12, $q${"en": {"label": "Five slow breaths"}, "he": {"label": "חמש נשימות איטיות"}, "es": {"label": "Cinco respiraciones lentas"}, "ru": {"label": "Пять медленных вдохов"}}$q$::jsonb
  where not exists (select 1 from public.mindset_ritual_catalog where label = $q$Cinq respirations lentes$q$);

insert into public.mindset_ritual_catalog (label, icon, sort_order, i18n)
  select $q$Trois lignes dans mon journal$q$, 'book', 13, $q${"en": {"label": "Three lines in my journal"}, "he": {"label": "שלוש שורות ביומן שלי"}, "es": {"label": "Tres líneas en mi diario"}, "ru": {"label": "Три строчки в дневнике"}}$q$::jsonb
  where not exists (select 1 from public.mindset_ritual_catalog where label = $q$Trois lignes dans mon journal$q$);


-- 3. Les trois parcours structurés (7 jours : Comprendre 1–2, Essayer 3–5, Ancrer 6–7).

insert into public.mindset_programs (slug, title, subtitle, description, for_you_if, minutes_range, day_count, sort_order, i18n)
  select 'installer-une-habitude', $q$Installer une nouvelle habitude$q$, $q$Faire de la place à un geste qui compte, jusqu'à ce qu'il se fasse tout seul.$q$, $q$Sept jours pour choisir un geste, l'accrocher à ton quotidien et le garder, sans forcer.$q$, $q$Tu as déjà essayé de prendre une habitude qui n'a pas tenu, tu préfères un geste simple à une révolution, ou tu es fatiguée de compter sur ta motivation.$q$, $q$5 à 10 min$q$, 7, 3, $q${"en": {"title": "Build a new habit", "subtitle": "Make room for a gesture that matters, until it happens on its own.", "description": "Seven days to choose one gesture, anchor it in your everyday life and keep it, without forcing.", "for_you_if": "You've tried to build a habit before and it didn't stick, you'd rather have one simple gesture than a revolution, or you're tired of relying on your motivation.", "minutes_range": "5–10 min"}, "he": {"title": "לבנות הרגל חדש", "subtitle": "לפנות מקום למחווה אחת שחשובה לך, עד שהיא קורית מעצמה.", "description": "שבעה ימים לבחור מחווה אחת, לעגן אותה ביומיום שלך ולשמור עליה, בלי להכריח.", "for_you_if": "כבר ניסית לאמץ הרגל שלא החזיק, את מעדיפה מחווה פשוטה על פני מהפכה, או שנמאס לך לסמוך על המוטיבציה.", "minutes_range": "5–10 דק׳"}, "es": {"title": "Instalar un nuevo hábito", "subtitle": "Hacer sitio a un gesto que importa, hasta que salga solo.", "description": "Siete días para elegir un gesto, anclarlo a tu día a día y conservarlo, sin forzar.", "for_you_if": "Ya has intentado adoptar un hábito que no duró, prefieres un gesto sencillo a una revolución, o estás cansada de depender de tu motivación.", "minutes_range": "5 a 10 min"}, "ru": {"title": "Завести новую привычку", "subtitle": "Дать место одному важному действию — пока оно не начнёт происходить само.", "description": "Семь дней, чтобы выбрать одно действие, привязать его к своему дню и сохранить, без усилий через силу.", "for_you_if": "Ты уже пробовала завести привычку, и она не прижилась; тебе ближе простое действие, чем революция; или ты устала полагаться на мотивацию.", "minutes_range": "5–10 мин"}}$q$::jsonb
  where not exists (select 1 from public.mindset_programs where slug = 'installer-une-habitude');

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 1, 'journal_prompt', $q$Choisir un seul geste$q$, $q$Quel geste aimerais-tu accueillir dans tes journées ? Écris-le en quelques mots.$q$, 'comprendre', $q$On a souvent envie de tout changer d'un coup. Pourtant, ce qui tient dans le temps commence presque toujours petit : un seul geste, assez simple pour être fait même un jour sans énergie.

Aujourd'hui, pas besoin d'agir. Juste de choisir. Pense à un geste qui te ferait du bien et qui prendrait moins de deux minutes : boire un verre d'eau, dérouler ton tapis, sortir respirer sur le pas de la porte.

S'il te semble presque trop facile, c'est bon signe. La facilité n'est pas un manque d'ambition : c'est ce qui permet au geste de revenir demain, puis après-demain.$q$, $q$Imagine-toi en train de faire ce geste, une fois, en entier.$q$, $q$Petit n'est pas moins. Petit, c'est ce qui revient.$q$, 5, 0, $q${"en": {"title": "Choose a single gesture", "idea": "We often want to change everything at once. Yet what lasts almost always starts small: one gesture, simple enough to do even on a day with no energy.\n\nToday, there's no need to act. Just choose. Think of a gesture that would do you good and take less than two minutes: drinking a glass of water, rolling out your mat, stepping outside to breathe on the doorstep.\n\nIf it feels almost too easy, that's a good sign. Ease isn't a lack of ambition: it's what lets the gesture come back tomorrow, and the day after.", "prompt_text": "Which gesture would you like to welcome into your days? Write it in a few words.", "gesture": "Picture yourself doing this gesture, once, from start to finish.", "take_away": "Small isn't less. Small is what comes back."}, "he": {"title": "לבחור מחווה אחת", "idea": "לעיתים קרובות מתחשק לשנות הכול בבת אחת. ובכל זאת, מה שמחזיק לאורך זמן מתחיל כמעט תמיד בקטן: מחווה אחת, פשוטה מספיק כדי לעשות אותה גם ביום בלי אנרגיה.\n\nהיום אין צורך לפעול. רק לבחור. חשבי על מחווה שתעשה לך טוב ותיקח פחות משתי דקות: לשתות כוס מים, לפרוש את המזרן, לצאת לנשום רגע בפתח הבית.\n\nאם היא נראית לך כמעט קלה מדי, זה סימן טוב. הקלות היא לא חוסר שאפתנות: היא מה שמאפשר למחווה לחזור מחר, ואחר כך מחרתיים.", "prompt_text": "איזו מחווה היית רוצה לקבל אל הימים שלך? כתבי אותה בכמה מילים.", "gesture": "דמייני את עצמך עושה את המחווה הזו, פעם אחת, מתחילתה ועד סופה.", "take_away": "קטן זה לא פחות. קטן זה מה שחוזר."}, "es": {"title": "Elegir un solo gesto", "idea": "A menudo queremos cambiarlo todo de golpe. Sin embargo, lo que dura casi siempre empieza pequeño: un solo gesto, lo bastante sencillo para hacerlo incluso un día sin energía.\n\nHoy no hace falta actuar. Solo elegir. Piensa en un gesto que te haría bien y que te llevaría menos de dos minutos: beber un vaso de agua, extender tu esterilla, salir a respirar a la puerta.\n\nSi te parece casi demasiado fácil, es buena señal. La facilidad no es falta de ambición: es lo que permite que el gesto vuelva mañana, y pasado mañana.", "prompt_text": "¿Qué gesto te gustaría acoger en tus días? Escríbelo en pocas palabras.", "gesture": "Imagínate haciendo este gesto, una vez, de principio a fin.", "take_away": "Pequeño no es menos. Pequeño es lo que vuelve."}, "ru": {"title": "Выбрать одно действие", "idea": "Часто хочется изменить всё сразу. Но то, что держится долго, почти всегда начинается с малого: с одного действия, настолько простого, что его можно сделать даже в день без сил.\n\nСегодня не нужно ничего делать. Только выбрать. Подумай о действии, которое пошло бы тебе на пользу и заняло бы меньше двух минут: выпить стакан воды, расстелить коврик, выйти подышать на порог.\n\nЕсли оно кажется почти слишком лёгким, это хороший знак. Лёгкость — не отсутствие амбиций: именно она позволяет действию вернуться завтра и послезавтра.", "prompt_text": "Какое действие тебе хотелось бы впустить в свои дни? Напиши о нём в нескольких словах.", "gesture": "Представь, как ты делаешь это действие — один раз, целиком.", "take_away": "Маленькое — не значит меньше. Маленькое — это то, что возвращается."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'installer-une-habitude'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 1);

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 2, 'journal_prompt', $q$Ce qui t'a freinée avant$q$, $q$La dernière fois qu'une habitude n'a pas tenu, qu'est-ce qui s'est mis en travers ?$q$, 'comprendre', $q$Si une habitude n'a pas tenu par le passé, ce n'est pas un défaut de caractère. Le plus souvent, le geste était trop grand, mal placé dans la journée, ou dépendait d'une motivation qui va et vient.

Repense à une fois où tu as lâché. Que s'est-il passé, concrètement ? Une semaine chargée, un réveil difficile, un « je le ferai plus tard » qui ne venait jamais ?

Regarder cela avec douceur, c'est déjà préparer la suite. Ce qui t'a freinée hier devient une information précieuse pour poser ton geste au bon endroit.$q$, $q$Fais ton geste une fois aujourd'hui, à n'importe quel moment.$q$, $q$Ce qui t'a arrêtée hier t'indique où poser le geste demain.$q$, 6, 0, $q${"en": {"title": "What held you back before", "idea": "If a habit didn't stick in the past, it isn't a flaw in your character. Most often, the gesture was too big, badly placed in the day, or depended on a motivation that comes and goes.\n\nThink back to a time you let go. What actually happened? A busy week, a hard morning, an \"I'll do it later\" that never came?\n\nLooking at this gently is already preparing what comes next. What held you back yesterday becomes precious information for placing your gesture in the right spot.", "prompt_text": "The last time a habit didn't stick, what got in the way?", "gesture": "Do your gesture once today, at any moment.", "take_away": "What stopped you yesterday shows you where to place the gesture tomorrow."}, "he": {"title": "מה עצר אותך בעבר", "idea": "אם הרגל לא החזיק בעבר, זה לא פגם באופי. לרוב המחווה הייתה גדולה מדי, ממוקמת לא נכון ביום, או תלויה במוטיבציה שבאה והולכת.\n\nחשבי על פעם שבה הרפית. מה קרה בפועל? שבוע עמוס, בוקר קשה, \"אעשה את זה אחר כך\" שאף פעם לא הגיע?\n\nלהביט בזה ברכות זה כבר להכין את ההמשך. מה שעצר אותך אתמול הופך למידע יקר ערך כדי למקם את המחווה במקום הנכון.", "prompt_text": "בפעם האחרונה שהרגל לא החזיק, מה נכנס בדרך?", "gesture": "עשי את המחווה שלך פעם אחת היום, בכל רגע שתבחרי.", "take_away": "מה שעצר אותך אתמול מראה לך איפה למקם את המחווה מחר."}, "es": {"title": "Lo que te frenó antes", "idea": "Si un hábito no duró en el pasado, no es un defecto de carácter. Lo más frecuente es que el gesto fuera demasiado grande, estuviera mal colocado en el día o dependiera de una motivación que va y viene.\n\nPiensa en una vez en que lo dejaste. ¿Qué pasó, en concreto? ¿Una semana cargada, un despertar difícil, un «ya lo haré luego» que nunca llegaba?\n\nMirarlo con suavidad ya es preparar lo que viene. Lo que te frenó ayer se convierte en una información valiosa para colocar tu gesto en el lugar adecuado.", "prompt_text": "La última vez que un hábito no duró, ¿qué se interpuso?", "gesture": "Haz tu gesto una vez hoy, en cualquier momento.", "take_away": "Lo que te detuvo ayer te indica dónde colocar el gesto mañana."}, "ru": {"title": "Что мешало раньше", "idea": "Если привычка раньше не прижилась, это не недостаток характера. Чаще всего действие было слишком большим, неудачно стояло в распорядке дня или зависело от мотивации, которая то приходит, то уходит.\n\nВспомни случай, когда ты бросила. Что произошло на самом деле? Загруженная неделя, тяжёлое утро, «сделаю потом», которое так и не наступило?\n\nМягко посмотреть на это — уже значит подготовить продолжение. То, что мешало вчера, становится ценной подсказкой, куда поставить действие.", "prompt_text": "Когда в последний раз привычка не прижилась, что помешало?", "gesture": "Сделай своё действие один раз сегодня, в любой момент.", "take_away": "То, что остановило тебя вчера, подсказывает, куда поставить действие завтра."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'installer-une-habitude'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 2);

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 3, 'journal_prompt', $q$Repérer tes moments fixes$q$, $q$Quels sont trois moments qui reviennent chaque jour dans ta journée ?$q$, 'essayer', $q$Ta journée a déjà ses repères : des choses que tu fais tous les jours sans y penser. Te brosser les dents, poser ta tasse de café, fermer la porte en rentrant, t'asseoir à ton bureau.

Ces moments sont solides parce qu'ils ne demandent aucun effort. Ce sont eux qui vont porter ton nouveau geste.

Aujourd'hui, observe-toi simplement. Note trois moments qui reviennent dans tes journées, week-end compris. Pas besoin de choisir tout de suite.$q$, $q$Pendant la journée, remarque tes moments fixes au moment où ils arrivent.$q$, $q$Tes journées ont déjà des repères. Il suffit de les voir.$q$, 6, 0, $q${"en": {"title": "Spot your fixed moments", "idea": "Your day already has its landmarks: things you do every day without thinking. Brushing your teeth, setting down your coffee cup, closing the door when you get home, sitting down at your desk.\n\nThese moments are solid because they take no effort. They're the ones that will carry your new gesture.\n\nToday, simply observe yourself. Note three moments that come back in your days, weekends included. No need to choose right away.", "prompt_text": "What are three moments that come back every day in your day?", "gesture": "During the day, notice your fixed moments as they happen.", "take_away": "Your days already have landmarks. You just need to see them."}, "he": {"title": "לזהות את הרגעים הקבועים שלך", "idea": "ליום שלך כבר יש עוגנים: דברים שאת עושה כל יום בלי לחשוב. לצחצח שיניים, להניח את כוס הקפה, לסגור את הדלת כשאת חוזרת הביתה, להתיישב ליד השולחן.\n\nהרגעים האלה יציבים כי הם לא דורשים שום מאמץ. הם אלה שיישאו את המחווה החדשה שלך.\n\nהיום פשוט התבונני בעצמך. רשמי שלושה רגעים שחוזרים בימים שלך, כולל בסופי שבוע. אין צורך לבחור עכשיו.", "prompt_text": "מהם שלושה רגעים שחוזרים כל יום ביום שלך?", "gesture": "במהלך היום, שימי לב לרגעים הקבועים שלך כשהם מגיעים.", "take_away": "לימים שלך כבר יש עוגנים. רק צריך לראות אותם."}, "es": {"title": "Detectar tus momentos fijos", "idea": "Tu día ya tiene sus referencias: cosas que haces todos los días sin pensar. Lavarte los dientes, dejar tu taza de café, cerrar la puerta al volver a casa, sentarte en tu escritorio.\n\nEstos momentos son sólidos porque no requieren ningún esfuerzo. Son ellos los que van a sostener tu nuevo gesto.\n\nHoy, simplemente obsérvate. Anota tres momentos que se repiten en tus días, fines de semana incluidos. No hace falta elegir todavía.", "prompt_text": "¿Cuáles son tres momentos que se repiten cada día en tu jornada?", "gesture": "Durante el día, fíjate en tus momentos fijos cuando llegan.", "take_away": "Tus días ya tienen referencias. Solo hace falta verlas."}, "ru": {"title": "Заметить свои постоянные моменты", "idea": "В твоём дне уже есть опоры: то, что ты делаешь каждый день, не задумываясь. Чистишь зубы, ставишь чашку кофе, закрываешь дверь, возвращаясь домой, садишься за рабочий стол.\n\nЭти моменты надёжны, потому что не требуют никаких усилий. Именно они понесут твоё новое действие.\n\nСегодня просто понаблюдай за собой. Запиши три момента, которые повторяются в твоих днях, включая выходные. Выбирать пока не нужно.", "prompt_text": "Какие три момента повторяются в твоём дне каждый день?", "gesture": "В течение дня замечай свои постоянные моменты, когда они наступают.", "take_away": "В твоих днях уже есть опоры. Нужно лишь их увидеть."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'installer-une-habitude'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 3);

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 4, 'journal_prompt', $q$Accrocher le geste$q$, $q$Écris ta phrase d'ancrage : « Après…, je… »$q$, 'essayer', $q$Un geste nouveau a besoin d'un point d'appui. Le plus solide, c'est un geste que tu fais déjà tous les jours sans y penser.

Hier, tu as repéré trois moments qui reviennent dans tes journées. C'est là qu'on va accrocher ton rituel, avec une phrase simple : « Après [ce que je fais déjà], je [mon geste]. » Après avoir posé ma tasse de café, je déroule mon tapis. Après m'être brossé les dents, j'ouvre mon livre.

Cette phrase a l'air anodine, mais elle remplace une intention floue (« je vais essayer de… ») par un moment précis. Le geste n'attend plus que tu y penses : c'est le moment d'avant qui te le rappelle.

Choisis un ancrage qui revient vraiment chaque jour, week-end compris, et place ton geste juste après, pas « dans la matinée ». Plus le lien est serré, mieux il tient.$q$, $q$Fais ton geste juste après ton ancrage.$q$, $q$Un nouveau geste tient mieux quand il s'accroche à un ancien.$q$, 6, 0, $q${"en": {"title": "Anchor the gesture", "idea": "A new gesture needs something to lean on. The strongest support is a gesture you already do every day without thinking.\n\nYesterday, you spotted three moments that come back in your days. That's where we'll anchor your ritual, with one simple sentence: \"After [what I already do], I [my gesture].\" After I set down my coffee cup, I roll out my mat. After I brush my teeth, I open my book.\n\nThis sentence looks harmless, but it replaces a vague intention (\"I'll try to…\") with a precise moment. The gesture no longer waits for you to think of it: the moment before reminds you.\n\nChoose an anchor that truly comes back every day, weekends included, and place your gesture right after it, not \"sometime in the morning\". The tighter the link, the better it holds.", "prompt_text": "Write your anchor sentence: \"After…, I…\"", "gesture": "Do your gesture right after your anchor.", "take_away": "A new gesture holds better when it hooks onto an old one."}, "he": {"title": "לעגן את המחווה", "idea": "מחווה חדשה צריכה נקודת משען. החזקה ביותר היא מחווה שאת כבר עושה כל יום בלי לחשוב.\n\nאתמול זיהית שלושה רגעים שחוזרים בימים שלך. שם נעגן את הטקס שלך, במשפט פשוט: \"אחרי [מה שאני כבר עושה], אני [המחווה שלי].\" אחרי שאני מניחה את כוס הקפה, אני פורשת את המזרן. אחרי שאני מצחצחת שיניים, אני פותחת את הספר.\n\nהמשפט הזה נראה תמים, אבל הוא מחליף כוונה מעורפלת (\"אנסה ל…\") ברגע מדויק. המחווה כבר לא מחכה שתיזכרי בה: הרגע שלפניה מזכיר לך.\n\nבחרי עוגן שבאמת חוזר כל יום, כולל בסופי שבוע, ומקמי את המחווה מיד אחריו, לא \"מתישהו בבוקר\". ככל שהקשר הדוק יותר, כך הוא מחזיק טוב יותר.", "prompt_text": "כתבי את משפט העוגן שלך: \"אחרי…, אני…\"", "gesture": "עשי את המחווה שלך מיד אחרי העוגן.", "take_away": "מחווה חדשה מחזיקה טוב יותר כשהיא נאחזת בישנה."}, "es": {"title": "Anclar el gesto", "idea": "Un gesto nuevo necesita un punto de apoyo. El más sólido es un gesto que ya haces todos los días sin pensar.\n\nAyer detectaste tres momentos que se repiten en tus días. Ahí es donde vamos a anclar tu ritual, con una frase sencilla: «Después de [lo que ya hago], yo [mi gesto].» Después de dejar mi taza de café, extiendo mi esterilla. Después de lavarme los dientes, abro mi libro.\n\nEsta frase parece insignificante, pero sustituye una intención vaga («voy a intentar…») por un momento preciso. El gesto ya no espera a que te acuerdes: es el momento anterior el que te lo recuerda.\n\nElige un ancla que se repita de verdad cada día, fines de semana incluidos, y coloca tu gesto justo después, no «durante la mañana». Cuanto más estrecho es el vínculo, mejor se mantiene.", "prompt_text": "Escribe tu frase de anclaje: «Después de…, yo…»", "gesture": "Haz tu gesto justo después de tu ancla.", "take_away": "Un gesto nuevo se sostiene mejor cuando se engancha a uno antiguo."}, "ru": {"title": "Привязать действие", "idea": "Новому действию нужна точка опоры. Самая надёжная — действие, которое ты уже делаешь каждый день, не задумываясь.\n\nВчера ты заметила три момента, которые повторяются в твоих днях. Именно к ним мы привяжем твой ритуал простой фразой: «После того как [то, что я уже делаю], я [моё действие].» После того как я ставлю чашку кофе, я расстилаю коврик. После того как я чищу зубы, я открываю книгу.\n\nЭта фраза кажется пустяком, но она заменяет размытое намерение («попробую…») точным моментом. Действию больше не нужно ждать, пока ты о нём вспомнишь: о нём напоминает предыдущий момент.\n\nВыбери опору, которая действительно повторяется каждый день, включая выходные, и поставь действие сразу после неё, а не «где-нибудь утром». Чем теснее связь, тем лучше она держится.", "prompt_text": "Напиши свою фразу-опору: «После того как…, я…»", "gesture": "Сделай своё действие сразу после опоры.", "take_away": "Новое действие держится лучше, когда цепляется за старое."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'installer-une-habitude'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 4);

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 5, 'journal_prompt', $q$Les jours sans$q$, $q$Qu'est-ce qui a rendu ton geste plus facile, ou plus difficile, ces derniers jours ?$q$, 'essayer', $q$Il y aura des jours où le geste ne se fera pas. Un enfant malade, un train raté, une fatigue qui tombe d'un coup. Ce n'est pas un échec, c'est la vie qui passe par là.

Ce qui compte, ce n'est pas de ne jamais manquer un jour, c'est de revenir le lendemain, sans te le reprocher. Un jour manqué n'efface pas ceux d'avant.

Aujourd'hui, regarde comment s'est passée ta semaine jusqu'ici, sans rien compter. Qu'est-ce qui a rendu le geste facile ? Qu'est-ce qui l'a rendu plus lourd ?$q$, $q$Fais ton geste après ton ancrage, même dans sa version la plus courte.$q$, $q$Revenir compte plus que ne jamais partir.$q$, 7, 0, $q${"en": {"title": "The days without", "idea": "There will be days when the gesture doesn't happen. A sick child, a missed train, a tiredness that hits all at once. That isn't failure, it's life passing through.\n\nWhat matters isn't never missing a day, it's coming back the next day, without blaming yourself. A missed day doesn't erase the ones before.\n\nToday, look at how your week has gone so far, without counting anything. What made the gesture easy? What made it heavier?", "prompt_text": "What made your gesture easier, or harder, these past few days?", "gesture": "Do your gesture after your anchor, even in its shortest version.", "take_away": "Coming back matters more than never leaving."}, "he": {"title": "הימים שבלי", "idea": "יהיו ימים שבהם המחווה לא תקרה. ילד חולה, רכבת שפספסת, עייפות שנופלת בבת אחת. זה לא כישלון, אלה החיים שעוברים שם.\n\nמה שחשוב הוא לא לעולם לא לפספס יום, אלא לחזור למחרת, בלי להאשים את עצמך. יום שפוספס לא מוחק את הימים שלפניו.\n\nהיום הביטי איך עבר עלייך השבוע עד עכשיו, בלי לספור כלום. מה הפך את המחווה לקלה? מה הפך אותה לכבדה יותר?", "prompt_text": "מה הפך את המחווה שלך לקלה יותר, או לקשה יותר, בימים האחרונים?", "gesture": "עשי את המחווה שלך אחרי העוגן, אפילו בגרסה הקצרה ביותר שלה.", "take_away": "לחזור חשוב יותר מלעולם לא לעזוב."}, "es": {"title": "Los días sin", "idea": "Habrá días en que el gesto no se haga. Un hijo enfermo, un tren perdido, un cansancio que cae de golpe. No es un fracaso, es la vida que pasa por ahí.\n\nLo que cuenta no es no faltar nunca un día, sino volver al día siguiente, sin reprochártelo. Un día que falta no borra los anteriores.\n\nHoy, mira cómo ha ido tu semana hasta ahora, sin contar nada. ¿Qué hizo que el gesto fuera fácil? ¿Qué lo hizo más pesado?", "prompt_text": "¿Qué hizo tu gesto más fácil, o más difícil, estos últimos días?", "gesture": "Haz tu gesto después de tu ancla, aunque sea en su versión más corta.", "take_away": "Volver cuenta más que no irse nunca."}, "ru": {"title": "Дни без", "idea": "Будут дни, когда действие не случится. Заболевший ребёнок, пропущенный поезд, усталость, которая наваливается разом. Это не провал, это жизнь проходит рядом.\n\nВажно не то, чтобы никогда не пропускать день, а то, чтобы вернуться на следующий, не упрекая себя. Пропущенный день не стирает предыдущие.\n\nСегодня посмотри, как прошла твоя неделя, ничего не подсчитывая. Что делало действие лёгким? Что делало его тяжелее?", "prompt_text": "Что делало твоё действие легче или труднее в последние дни?", "gesture": "Сделай действие после опоры, хотя бы в самой короткой версии.", "take_away": "Возвращаться важнее, чем никогда не уходить."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'installer-une-habitude'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 5);

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 6, 'journal_prompt', $q$Ta version de secours$q$, $q$Quelle est la version la plus petite de ton geste, celle que tu peux faire même un jour difficile ?$q$, 'ancrer', $q$Les jours chargés, le geste complet peut sembler hors de portée. Plutôt que de le laisser tomber, tu peux prévoir une version minuscule, qui garde le lien vivant.

Si ton geste est de dérouler ton tapis pour dix minutes, ta version de secours peut être de t'asseoir une minute dessus. Si c'est lire, ce sera une seule page.

Cette version n'est pas un plan B honteux. C'est elle qui protège ton rituel les jours où tout déborde, et qui te permet de dire : je l'ai fait quand même, à ma façon.$q$, $q$Essaie ta version de secours une fois, pour sentir qu'elle existe.$q$, $q$Une minute garde le fil. Le fil, c'est tout ce qui compte.$q$, 6, 0, $q${"en": {"title": "Your backup version", "idea": "On busy days, the full gesture can feel out of reach. Rather than dropping it, you can plan a tiny version that keeps the link alive.\n\nIf your gesture is rolling out your mat for ten minutes, your backup version can be sitting on it for one minute. If it's reading, it will be a single page.\n\nThis version isn't a shameful plan B. It's what protects your ritual on days when everything overflows, and lets you say: I did it anyway, my way.", "prompt_text": "What's the smallest version of your gesture, the one you can do even on a hard day?", "gesture": "Try your backup version once, to feel that it exists.", "take_away": "One minute keeps the thread. The thread is all that matters."}, "he": {"title": "גרסת הגיבוי שלך", "idea": "בימים עמוסים, המחווה המלאה יכולה להיראות רחוקה מדי. במקום לוותר עליה, את יכולה להכין גרסה זעירה ששומרת על הקשר חי.\n\nאם המחווה שלך היא לפרוש את המזרן לעשר דקות, גרסת הגיבוי יכולה להיות לשבת עליו דקה אחת. אם זו קריאה, זה יהיה עמוד אחד.\n\nהגרסה הזו היא לא תוכנית ב׳ מביישת. היא זו ששומרת על הטקס שלך בימים שבהם הכול גולש, ומאפשרת לך לומר: עשיתי את זה בכל זאת, בדרך שלי.", "prompt_text": "מהי הגרסה הקטנה ביותר של המחווה שלך, זו שאת יכולה לעשות גם ביום קשה?", "gesture": "נסי את גרסת הגיבוי שלך פעם אחת, כדי להרגיש שהיא קיימת.", "take_away": "דקה אחת שומרת על החוט. החוט הוא כל מה שחשוב."}, "es": {"title": "Tu versión de emergencia", "idea": "Los días cargados, el gesto completo puede parecer fuera de alcance. En lugar de dejarlo caer, puedes prever una versión minúscula que mantenga vivo el vínculo.\n\nSi tu gesto es extender tu esterilla durante diez minutos, tu versión de emergencia puede ser sentarte un minuto encima. Si es leer, será una sola página.\n\nEsta versión no es un plan B vergonzoso. Es la que protege tu ritual los días en que todo se desborda, y la que te permite decir: lo hice igualmente, a mi manera.", "prompt_text": "¿Cuál es la versión más pequeña de tu gesto, la que puedes hacer incluso un día difícil?", "gesture": "Prueba tu versión de emergencia una vez, para sentir que existe.", "take_away": "Un minuto mantiene el hilo. El hilo es todo lo que importa."}, "ru": {"title": "Твоя запасная версия", "idea": "В загруженные дни полное действие может казаться недостижимым. Вместо того чтобы бросить его, можно заранее придумать крошечную версию, которая сохранит связь.\n\nЕсли твоё действие — расстелить коврик на десять минут, запасной версией может стать одна минута, проведённая на нём сидя. Если это чтение — одна страница.\n\nЭта версия — не постыдный план Б. Именно она бережёт твой ритуал в дни, когда всё через край, и позволяет сказать: я всё-таки сделала это, по-своему.", "prompt_text": "Какая самая маленькая версия твоего действия — та, что получится даже в трудный день?", "gesture": "Попробуй запасную версию один раз, чтобы почувствовать, что она есть.", "take_away": "Одна минута сохраняет нить. А нить — это главное."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'installer-une-habitude'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 6);

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 7, 'journal_prompt', $q$Ta marque de satisfaction$q$, $q$Comment vas-tu marquer la fin de ton geste, pour te dire « c'est fait » ?$q$, 'ancrer', $q$Un geste se garde plus facilement quand il se termine par un petit moment agréable. Pas une récompense à mériter : juste une façon de dire « c'est fait » à ton corps.

Ça peut être une longue respiration, une main posée sur le cœur, un sourire, un « voilà » à voix basse. Quelque chose de simple, qui ne coûte rien et qui te ressemble.

Avec ton ancrage, ta version de secours et cette marque, ton geste a tout ce qu'il lui faut. Le parcours se termine, mais le geste, lui, peut continuer.$q$, $q$Fais ton geste, puis offre-toi ta marque de satisfaction.$q$, $q$Ce que tu fais pour toi mérite d'être savouré.$q$, 7, 0, $q${"en": {"title": "Your mark of satisfaction", "idea": "A gesture is easier to keep when it ends with a small pleasant moment. Not a reward to earn: just a way of telling your body \"done\".\n\nIt can be a long breath, a hand on your heart, a smile, a quiet \"there\". Something simple that costs nothing and feels like you.\n\nWith your anchor, your backup version and this mark, your gesture has everything it needs. The journey ends, but the gesture can carry on.", "prompt_text": "How will you mark the end of your gesture, to tell yourself \"done\"?", "gesture": "Do your gesture, then give yourself your mark of satisfaction.", "take_away": "What you do for yourself deserves to be savoured."}, "he": {"title": "סימן הסיפוק שלך", "idea": "קל יותר לשמור על מחווה כשהיא מסתיימת ברגע קטן ונעים. לא פרס שצריך להרוויח: רק דרך לומר לגוף שלך \"זהו, עשיתי\".\n\nזה יכול להיות נשימה ארוכה, יד מונחת על הלב, חיוך, \"הנה\" בשקט. משהו פשוט, שלא עולה כלום ושדומה לך.\n\nעם העוגן שלך, גרסת הגיבוי והסימן הזה, למחווה שלך יש כל מה שהיא צריכה. המסלול מסתיים, אבל המחווה יכולה להמשיך.", "prompt_text": "איך תסמני את סוף המחווה שלך, כדי לומר לעצמך \"זהו, עשיתי\"?", "gesture": "עשי את המחווה שלך, ואז העניקי לעצמך את סימן הסיפוק שלך.", "take_away": "מה שאת עושה בשביל עצמך ראוי שתתענגי עליו."}, "es": {"title": "Tu señal de satisfacción", "idea": "Un gesto se conserva más fácilmente cuando termina con un pequeño momento agradable. No una recompensa que merecer: solo una forma de decirle «hecho» a tu cuerpo.\n\nPuede ser una respiración larga, una mano sobre el corazón, una sonrisa, un «ya está» en voz baja. Algo sencillo, que no cuesta nada y que se parece a ti.\n\nCon tu ancla, tu versión de emergencia y esta señal, tu gesto tiene todo lo que necesita. El recorrido termina, pero el gesto puede continuar.", "prompt_text": "¿Cómo vas a marcar el final de tu gesto, para decirte «hecho»?", "gesture": "Haz tu gesto y luego regálate tu señal de satisfacción.", "take_away": "Lo que haces por ti merece ser saboreado."}, "ru": {"title": "Твой знак удовлетворения", "idea": "Действие легче сохранить, когда оно заканчивается маленьким приятным моментом. Не наградой, которую нужно заслужить, а просто способом сказать телу «готово».\n\nЭто может быть долгий вдох, ладонь на сердце, улыбка, тихое «вот». Что-то простое, ничего не стоящее и похожее на тебя.\n\nС опорой, запасной версией и этим знаком у твоего действия есть всё необходимое. Путь заканчивается, а действие может продолжаться.", "prompt_text": "Как ты отметишь окончание своего действия, чтобы сказать себе «готово»?", "gesture": "Сделай своё действие, а потом подари себе свой знак удовлетворения.", "take_away": "То, что ты делаешь для себя, стоит того, чтобы им насладиться."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'installer-une-habitude'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 7);

insert into public.mindset_programs (slug, title, subtitle, description, for_you_if, minutes_range, day_count, sort_order, i18n)
  select 'ecouter-sa-faim', $q$Écouter sa faim$q$, $q$Retrouver les signaux de ton corps, sans règles ni interdits.$q$, $q$Sept jours pour réapprendre à reconnaître ta faim et le moment où tu n'as plus faim, à ton rythme.$q$, $q$Tu manges parfois sans vraiment savoir si tu as faim, tu as l'impression de ne plus entendre ton corps, ou tu as envie de faire la paix avec tes repas, tranquillement.$q$, $q$5 à 10 min$q$, 7, 4, $q${"en": {"title": "Listen to your hunger", "subtitle": "Find your body's signals again, without rules or bans.", "description": "Seven days to relearn how to recognise your hunger and the moment you're no longer hungry, at your own pace.", "for_you_if": "You sometimes eat without really knowing if you're hungry, you feel you can't hear your body anymore, or you'd like to make peace with your meals, calmly.", "minutes_range": "5–10 min"}, "he": {"title": "להקשיב לרעב שלך", "subtitle": "למצוא מחדש את האותות של הגוף שלך, בלי חוקים ובלי איסורים.", "description": "שבעה ימים ללמוד מחדש לזהות את הרעב שלך ואת הרגע שבו את כבר לא רעבה, בקצב שלך.", "for_you_if": "לפעמים את אוכלת בלי לדעת באמת אם את רעבה, את מרגישה שכבר לא שומעת את הגוף שלך, או שמתחשק לך לעשות שלום עם הארוחות שלך, בנחת.", "minutes_range": "5–10 דק׳"}, "es": {"title": "Escuchar tu hambre", "subtitle": "Recuperar las señales de tu cuerpo, sin reglas ni prohibiciones.", "description": "Siete días para volver a reconocer tu hambre y el momento en que ya no tienes hambre, a tu ritmo.", "for_you_if": "A veces comes sin saber de verdad si tienes hambre, sientes que ya no oyes a tu cuerpo, o te apetece hacer las paces con tus comidas, con calma.", "minutes_range": "5 a 10 min"}, "ru": {"title": "Слушать свой голод", "subtitle": "Снова услышать сигналы своего тела — без правил и запретов.", "description": "Семь дней, чтобы заново научиться узнавать голод и момент, когда ты уже не голодна, в своём ритме.", "for_you_if": "Ты иногда ешь, не понимая, голодна ли ты; тебе кажется, что ты перестала слышать своё тело; или тебе хочется спокойно примириться со своими приёмами пищи.", "minutes_range": "5–10 мин"}}$q$::jsonb
  where not exists (select 1 from public.mindset_programs where slug = 'ecouter-sa-faim');

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 1, 'journal_prompt', $q$Les visages de la faim$q$, $q$Comment reconnais-tu la faim dans ton corps ? Où la sens-tu ?$q$, 'comprendre', $q$La faim n'a pas qu'un seul visage. Il y a la faim du corps, qui monte doucement : un creux, une baisse d'énergie, du mal à te concentrer. Et il y a les autres envies de manger : la fatigue, l'ennui, une émotion, une habitude.

Aucune n'est mauvaise. Toutes disent quelque chose de toi. L'idée n'est pas de les trier, mais d'apprendre à les reconnaître.

Aujourd'hui, avant un repas ou un en-cas, prends simplement une seconde pour te demander : qu'est-ce qui me donne envie de manger, là ?$q$, $q$Avant de manger, pose-toi une seule question : « est-ce que j'ai faim ? »$q$, $q$Ta faim te parle. Tu as le droit de l'écouter.$q$, 5, 0, $q${"en": {"title": "The faces of hunger", "idea": "Hunger doesn't have just one face. There's the body's hunger, which rises gently: an empty feeling, a dip in energy, trouble concentrating. And there are other urges to eat: tiredness, boredom, an emotion, a habit.\n\nNone of them is bad. They all say something about you. The idea isn't to sort them, but to learn to recognise them.\n\nToday, before a meal or a snack, simply take a second to ask yourself: what is making me want to eat, right now?", "prompt_text": "How do you recognise hunger in your body? Where do you feel it?", "gesture": "Before eating, ask yourself just one question: \"am I hungry?\"", "take_away": "Your hunger is talking to you. You're allowed to listen."}, "he": {"title": "הפנים של הרעב", "idea": "לרעב אין רק פנים אחדות. יש את הרעב של הגוף, שעולה בעדינות: תחושת ריקנות, ירידה באנרגיה, קושי להתרכז. ויש את שאר הדחפים לאכול: עייפות, שעמום, רגש, הרגל.\n\nאף אחד מהם אינו רע. כולם אומרים משהו עלייך. הרעיון הוא לא למיין אותם, אלא ללמוד לזהות אותם.\n\nהיום, לפני ארוחה או נשנוש, קחי שנייה אחת לשאול את עצמך: מה גורם לי לרצות לאכול, עכשיו?", "prompt_text": "איך את מזהה את הרעב בגוף שלך? איפה את מרגישה אותו?", "gesture": "לפני שאת אוכלת, שאלי את עצמך שאלה אחת בלבד: \"האם אני רעבה?\"", "take_away": "הרעב שלך מדבר אלייך. מותר לך להקשיב לו."}, "es": {"title": "Las caras del hambre", "idea": "El hambre no tiene una sola cara. Está el hambre del cuerpo, que sube despacio: un vacío, una bajada de energía, dificultad para concentrarte. Y están las otras ganas de comer: el cansancio, el aburrimiento, una emoción, una costumbre.\n\nNinguna es mala. Todas dicen algo de ti. La idea no es clasificarlas, sino aprender a reconocerlas.\n\nHoy, antes de una comida o un tentempié, tómate solo un segundo para preguntarte: ¿qué me da ganas de comer, ahora?", "prompt_text": "¿Cómo reconoces el hambre en tu cuerpo? ¿Dónde la sientes?", "gesture": "Antes de comer, hazte una sola pregunta: «¿tengo hambre?»", "take_away": "Tu hambre te habla. Tienes derecho a escucharla."}, "ru": {"title": "Лица голода", "idea": "У голода не одно лицо. Есть голод тела, который поднимается постепенно: пустота внутри, спад энергии, трудно сосредоточиться. А есть другие желания поесть: усталость, скука, эмоция, привычка.\n\nНи одно из них не плохое. Все они что-то говорят о тебе. Задача не в том, чтобы их сортировать, а в том, чтобы научиться их узнавать.\n\nСегодня перед едой или перекусом просто остановись на секунду и спроси себя: что сейчас вызывает у меня желание поесть?", "prompt_text": "Как ты узнаёшь голод в своём теле? Где ты его чувствуешь?", "gesture": "Перед едой задай себе всего один вопрос: «я голодна?»", "take_away": "Твой голод говорит с тобой. Ты вправе его слушать."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'ecouter-sa-faim'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 1);

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 2, 'journal_prompt', $q$Ton histoire avec les repas$q$, $q$Quelle phrase ou quelle règle sur la nourriture t'accompagne depuis longtemps ?$q$, 'comprendre', $q$Chacune arrive avec une histoire : des règles entendues enfant, des périodes où l'on s'est privée, des repas avalés debout. Tout cela laisse des traces, et c'est normal.

Ces traces expliquent pourquoi il peut être difficile d'entendre sa faim aujourd'hui. Le signal est toujours là ; il a juste été couvert par beaucoup de bruit.

Pas besoin de tout démêler. Remarque seulement une phrase ou une habitude qui t'accompagne encore à table.$q$, $q$Prends un repas aujourd'hui assise, sans écran, même court.$q$, $q$Ce que tu as appris peut se réapprendre, doucement.$q$, 6, 0, $q${"en": {"title": "Your story with meals", "idea": "Each of us arrives with a story: rules heard as a child, periods of going without, meals eaten standing up. All of this leaves traces, and that's normal.\n\nThese traces explain why it can be hard to hear your hunger today. The signal is still there; it's just been covered by a lot of noise.\n\nNo need to untangle everything. Just notice one phrase or habit that still comes to the table with you.", "prompt_text": "Which phrase or rule about food has been with you for a long time?", "gesture": "Have one meal today sitting down, without a screen, even a short one.", "take_away": "What you learned can be relearned, gently."}, "he": {"title": "הסיפור שלך עם הארוחות", "idea": "כל אחת מגיעה עם סיפור: חוקים ששמעה בילדות, תקופות שבהן מנעה מעצמה, ארוחות שנבלעו בעמידה. כל זה משאיר עקבות, וזה טבעי.\n\nהעקבות האלה מסבירים למה קשה לפעמים לשמוע את הרעב היום. האות עדיין שם; הוא פשוט כוסה בהרבה רעש.\n\nאין צורך להתיר הכול. רק שימי לב למשפט אחד או להרגל אחד שעדיין מלווה אותך לשולחן.", "prompt_text": "איזה משפט או איזה חוק על אוכל מלווה אותך כבר הרבה זמן?", "gesture": "אכלי היום ארוחה אחת בישיבה, בלי מסך, גם אם קצרה.", "take_away": "מה שלמדת אפשר ללמוד מחדש, בעדינות."}, "es": {"title": "Tu historia con las comidas", "idea": "Cada una llega con una historia: reglas oídas de niña, épocas en que nos privamos, comidas tragadas de pie. Todo eso deja huellas, y es normal.\n\nEsas huellas explican por qué puede costar oír el hambre hoy. La señal sigue ahí; simplemente la ha tapado mucho ruido.\n\nNo hace falta desenredarlo todo. Fíjate solo en una frase o una costumbre que todavía te acompaña a la mesa.", "prompt_text": "¿Qué frase o qué regla sobre la comida te acompaña desde hace tiempo?", "gesture": "Haz hoy una comida sentada, sin pantalla, aunque sea corta.", "take_away": "Lo que aprendiste se puede volver a aprender, con suavidad."}, "ru": {"title": "Твоя история с едой", "idea": "Каждая приходит со своей историей: правила, услышанные в детстве, периоды, когда мы себя ограничивали, еда на бегу. Всё это оставляет следы, и это нормально.\n\nЭти следы объясняют, почему сегодня бывает трудно услышать голод. Сигнал никуда не делся — его просто заглушил шум.\n\nНе нужно распутывать всё. Просто заметь одну фразу или привычку, которая до сих пор садится с тобой за стол.", "prompt_text": "Какая фраза или правило о еде сопровождает тебя уже давно?", "gesture": "Поешь сегодня один раз сидя, без экрана, пусть даже недолго.", "take_away": "То, чему ты научилась, можно переучить — бережно."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'ecouter-sa-faim'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 2);

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 3, 'journal_prompt', $q$Les nuances de ta faim$q$, $q$Avant ton dernier repas, quel mot aurais-tu mis sur ta faim ?$q$, 'essayer', $q$La faim a des nuances : un petit creux, une faim tranquille, une faim pressante qui rend impatiente. Plus tu les connais, plus tu peux choisir le moment de manger.

Souvent, on attend la faim pressante, et le repas file trop vite. Ou on mange sans faim, par habitude. Entre les deux, il y a un moment confortable pour se mettre à table.

Aujourd'hui, essaie de mettre un mot sur ta faim avant chaque repas. Pas pour la juger : juste pour la nommer.$q$, $q$Avant chaque repas, nomme ta faim d'un mot.$q$, $q$Nommer ta faim, c'est déjà l'entendre.$q$, 6, 0, $q${"en": {"title": "The shades of your hunger", "idea": "Hunger has shades: a slight emptiness, a calm hunger, an urgent hunger that makes you impatient. The better you know them, the more you can choose when to eat.\n\nOften we wait for urgent hunger, and the meal goes by too fast. Or we eat without hunger, out of habit. In between, there's a comfortable moment to sit down and eat.\n\nToday, try to put a word on your hunger before each meal. Not to judge it: just to name it.", "prompt_text": "Before your last meal, what word would you have put on your hunger?", "gesture": "Before each meal, name your hunger in one word.", "take_away": "Naming your hunger is already hearing it."}, "he": {"title": "הגוונים של הרעב שלך", "idea": "לרעב יש גוונים: ריקנות קלה, רעב שקט, רעב דוחק שגורם לחוסר סבלנות. ככל שתכירי אותם יותר, כך תוכלי לבחור מתי לאכול.\n\nלעיתים קרובות מחכים לרעב הדוחק, והארוחה חולפת מהר מדי. או שאוכלים בלי רעב, מתוך הרגל. בין שני אלה יש רגע נוח לשבת לשולחן.\n\nהיום נסי לתת מילה לרעב שלך לפני כל ארוחה. לא כדי לשפוט אותו: רק כדי לקרוא לו בשם.", "prompt_text": "לפני הארוחה האחרונה שלך, איזו מילה היית נותנת לרעב שלך?", "gesture": "לפני כל ארוחה, תני לרעב שלך שם במילה אחת.", "take_away": "לקרוא לרעב בשם זה כבר לשמוע אותו."}, "es": {"title": "Los matices de tu hambre", "idea": "El hambre tiene matices: un pequeño vacío, un hambre tranquila, un hambre apremiante que impacienta. Cuanto mejor los conoces, más puedes elegir el momento de comer.\n\nA menudo esperamos al hambre apremiante y la comida pasa demasiado rápido. O comemos sin hambre, por costumbre. Entre las dos hay un momento cómodo para sentarse a la mesa.\n\nHoy, intenta poner una palabra a tu hambre antes de cada comida. No para juzgarla: solo para nombrarla.", "prompt_text": "Antes de tu última comida, ¿qué palabra le habrías puesto a tu hambre?", "gesture": "Antes de cada comida, nombra tu hambre con una palabra.", "take_away": "Nombrar tu hambre ya es escucharla."}, "ru": {"title": "Оттенки твоего голода", "idea": "У голода есть оттенки: лёгкая пустота, спокойный голод, острый голод, от которого становишься нетерпеливой. Чем лучше ты их знаешь, тем свободнее выбираешь, когда есть.\n\nЧасто мы ждём острого голода, и еда пролетает слишком быстро. Или едим без голода, по привычке. Между ними есть комфортный момент, чтобы сесть за стол.\n\nСегодня попробуй перед каждым приёмом пищи назвать свой голод одним словом. Не чтобы его оценить — просто чтобы назвать.", "prompt_text": "Каким словом ты назвала бы свой голод перед последним приёмом пищи?", "gesture": "Перед каждым приёмом пищи назови свой голод одним словом.", "take_away": "Назвать голод — значит уже его услышать."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'ecouter-sa-faim'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 3);

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 4, 'journal_prompt', $q$Une pause avant de manger$q$, $q$Écris ta phrase d'ancrage pour ta pause : « Après…, je… »$q$, 'essayer', $q$Pour entendre ta faim, il faut un petit espace. Une pause de quelques secondes avant de manger suffit : le temps de respirer et de sentir où tu en es.

Comme pour toute habitude, cette pause tient mieux si elle s'accroche à un geste que tu fais déjà : t'asseoir, poser ton assiette, déplier ta serviette. « Après m'être assise, je prends une respiration et j'écoute ma faim. »

Choisis un moment présent à chaque repas, et place ta pause juste après. Elle deviendra peu à peu un réflexe, presque sans y penser.$q$, $q$Fais ta pause juste après ton ancrage, à chaque repas.$q$, $q$Une respiration avant de manger, et ton corps a la parole.$q$, 6, 0, $q${"en": {"title": "A pause before eating", "idea": "To hear your hunger, you need a little space. A pause of a few seconds before eating is enough: time to breathe and feel where you are.\n\nAs with any habit, this pause holds better if it hooks onto a gesture you already do: sitting down, setting down your plate, unfolding your napkin. \"After I sit down, I take a breath and listen to my hunger.\"\n\nChoose a moment that's there at every meal, and place your pause right after it. Little by little it will become a reflex, almost without thinking.", "prompt_text": "Write your anchor sentence for your pause: \"After…, I…\"", "gesture": "Take your pause right after your anchor, at every meal.", "take_away": "One breath before eating, and your body gets to speak."}, "he": {"title": "הפסקה לפני האוכל", "idea": "כדי לשמוע את הרעב שלך צריך מרווח קטן. הפסקה של כמה שניות לפני האוכל מספיקה: זמן לנשום ולהרגיש איפה את נמצאת.\n\nכמו בכל הרגל, ההפסקה הזו מחזיקה טוב יותר אם היא נאחזת במחווה שאת כבר עושה: להתיישב, להניח את הצלחת, לפרוש את המפית. \"אחרי שאני מתיישבת, אני לוקחת נשימה ומקשיבה לרעב שלי.\"\n\nבחרי רגע שקיים בכל ארוחה, ומקמי את ההפסקה מיד אחריו. לאט לאט היא תהפוך לרפלקס, כמעט בלי לחשוב.", "prompt_text": "כתבי את משפט העוגן להפסקה שלך: \"אחרי…, אני…\"", "gesture": "עשי את ההפסקה מיד אחרי העוגן, בכל ארוחה.", "take_away": "נשימה אחת לפני האוכל, והגוף שלך מקבל את רשות הדיבור."}, "es": {"title": "Una pausa antes de comer", "idea": "Para oír tu hambre hace falta un pequeño espacio. Una pausa de unos segundos antes de comer basta: el tiempo de respirar y sentir cómo estás.\n\nComo cualquier hábito, esta pausa se mantiene mejor si se engancha a un gesto que ya haces: sentarte, dejar el plato, desplegar la servilleta. «Después de sentarme, respiro y escucho mi hambre.»\n\nElige un momento presente en cada comida y coloca tu pausa justo después. Poco a poco se convertirá en un reflejo, casi sin pensar.", "prompt_text": "Escribe tu frase de anclaje para tu pausa: «Después de…, yo…»", "gesture": "Haz tu pausa justo después de tu ancla, en cada comida.", "take_away": "Una respiración antes de comer, y tu cuerpo toma la palabra."}, "ru": {"title": "Пауза перед едой", "idea": "Чтобы услышать голод, нужно немного пространства. Достаточно паузы в несколько секунд перед едой: время вдохнуть и почувствовать, как ты.\n\nКак и любая привычка, эта пауза держится лучше, если цепляется за действие, которое ты уже делаешь: сесть, поставить тарелку, развернуть салфетку. «После того как я сажусь, я делаю вдох и прислушиваюсь к голоду.»\n\nВыбери момент, который есть в каждом приёме пищи, и поставь паузу сразу после него. Постепенно она станет рефлексом, почти без размышлений.", "prompt_text": "Напиши фразу-опору для своей паузы: «После того как…, я…»", "gesture": "Делай паузу сразу после опоры, за каждой едой.", "take_away": "Один вдох перед едой — и слово за твоим телом."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'ecouter-sa-faim'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 4);

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 5, 'journal_prompt', $q$Sentir quand c'est assez$q$, $q$À quoi ressemble, pour toi, le moment où tu n'as plus faim ?$q$, 'essayer', $q$Le moment où l'on n'a plus faim arrive plus doucement que la faim. Il demande un peu de temps pour se faire entendre, souvent une vingtaine de minutes après le début du repas.

Il peut ressembler à un apaisement, une envie moins forte, un plat qui devient moins intéressant. Ce n'est pas un signal pour t'arrêter à tout prix, juste une information.

Aujourd'hui, au milieu d'un repas, pose ta fourchette un instant. Écoute. Puis continue, ou arrête-toi, comme ton corps le sent.$q$, $q$Au milieu d'un repas, pose ta fourchette quelques secondes.$q$, $q$Ton corps sait dire assez. Laisse-lui le temps.$q$, 7, 0, $q${"en": {"title": "Feeling when it's enough", "idea": "The moment you're no longer hungry arrives more gently than hunger. It needs a little time to be heard, often about twenty minutes after the meal begins.\n\nIt can feel like a settling, a weaker urge, a dish that becomes less interesting. It isn't a signal to stop at all costs, just information.\n\nToday, in the middle of a meal, put your fork down for a moment. Listen. Then carry on, or stop, as your body feels.", "prompt_text": "What does the moment you're no longer hungry feel like for you?", "gesture": "In the middle of a meal, put your fork down for a few seconds.", "take_away": "Your body knows how to say enough. Give it time."}, "he": {"title": "להרגיש מתי זה מספיק", "idea": "הרגע שבו כבר לא רעבים מגיע בעדינות רבה יותר מהרעב. הוא צריך קצת זמן כדי להישמע, לרוב כעשרים דקות אחרי תחילת הארוחה.\n\nהוא יכול להרגיש כמו רגיעה, דחף חלש יותר, מנה שהופכת לפחות מעניינת. זה לא אות לעצור בכל מחיר, רק מידע.\n\nהיום, באמצע ארוחה, הניחי את המזלג לרגע. הקשיבי. ואז המשיכי, או עצרי, כפי שהגוף שלך מרגיש.", "prompt_text": "איך מרגיש אצלך הרגע שבו את כבר לא רעבה?", "gesture": "באמצע ארוחה, הניחי את המזלג לכמה שניות.", "take_away": "הגוף שלך יודע לומר די. תני לו זמן."}, "es": {"title": "Sentir cuándo es suficiente", "idea": "El momento en que ya no tienes hambre llega más despacio que el hambre. Necesita un poco de tiempo para hacerse oír, a menudo unos veinte minutos después de empezar a comer.\n\nPuede parecerse a un sosiego, unas ganas menos fuertes, un plato que se vuelve menos interesante. No es una señal para parar a toda costa, solo una información.\n\nHoy, a mitad de una comida, deja el tenedor un instante. Escucha. Luego sigue, o para, como lo sienta tu cuerpo.", "prompt_text": "¿Cómo es, para ti, el momento en que ya no tienes hambre?", "gesture": "A mitad de una comida, deja el tenedor unos segundos.", "take_away": "Tu cuerpo sabe decir basta. Dale tiempo."}, "ru": {"title": "Почувствовать, что достаточно", "idea": "Момент, когда голод уходит, наступает мягче, чем сам голод. Ему нужно немного времени, чтобы дать о себе знать, — часто около двадцати минут от начала еды.\n\nОн может ощущаться как успокоение, ослабевшее желание, блюдо, которое становится менее интересным. Это не сигнал остановиться любой ценой, а просто информация.\n\nСегодня в середине еды положи вилку на мгновение. Прислушайся. Потом продолжай или остановись — как подскажет тело.", "prompt_text": "Как для тебя ощущается момент, когда ты уже не голодна?", "gesture": "В середине еды положи вилку на несколько секунд.", "take_away": "Твоё тело умеет сказать «хватит». Дай ему время."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'ecouter-sa-faim'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 5);

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 6, 'journal_prompt', $q$Ta version de secours$q$, $q$Quelle est la version la plus courte de ta pause, pour les repas pressés ?$q$, 'ancrer', $q$Certains repas se prennent en courant : au bureau, en voiture, entre deux rendez-vous. Ces jours-là, la pause complète paraît impossible.

Prévois une version minuscule : une seule respiration avant la première bouchée, ou simplement te demander « j'ai faim comment, là ? ». Cela garde le lien avec ton corps, même dans le bruit.

Ce n'est pas faire moins bien. C'est rester à l'écoute, à la mesure de ta journée.$q$, $q$Essaie ta version de secours lors d'un repas pressé.$q$, $q$Même une seule respiration te ramène à toi.$q$, 6, 0, $q${"en": {"title": "Your backup version", "idea": "Some meals happen on the run: at the office, in the car, between two appointments. On those days, the full pause seems impossible.\n\nPlan a tiny version: a single breath before the first bite, or simply asking yourself \"how hungry am I, right now?\". It keeps the link with your body, even in the noise.\n\nIt isn't doing it less well. It's staying attentive, in proportion to your day.", "prompt_text": "What's the shortest version of your pause, for rushed meals?", "gesture": "Try your backup version during a rushed meal.", "take_away": "Even a single breath brings you back to yourself."}, "he": {"title": "גרסת הגיבוי שלך", "idea": "יש ארוחות שנאכלות בריצה: במשרד, באוטו, בין שתי פגישות. בימים כאלה, ההפסקה המלאה נראית בלתי אפשרית.\n\nהכיני גרסה זעירה: נשימה אחת לפני הביס הראשון, או פשוט לשאול את עצמך \"כמה אני רעבה, עכשיו?\". זה שומר על הקשר עם הגוף שלך, גם בתוך הרעש.\n\nזה לא לעשות פחות טוב. זה להישאר קשובה, במידה שמתאימה ליום שלך.", "prompt_text": "מהי הגרסה הקצרה ביותר של ההפסקה שלך, לארוחות חפוזות?", "gesture": "נסי את גרסת הגיבוי שלך בארוחה חפוזה.", "take_away": "אפילו נשימה אחת מחזירה אותך אל עצמך."}, "es": {"title": "Tu versión de emergencia", "idea": "Algunas comidas se hacen corriendo: en la oficina, en el coche, entre dos citas. Esos días, la pausa completa parece imposible.\n\nPrevé una versión minúscula: una sola respiración antes del primer bocado, o simplemente preguntarte «¿cuánta hambre tengo, ahora?». Eso mantiene el vínculo con tu cuerpo, incluso en medio del ruido.\n\nNo es hacerlo peor. Es seguir escuchando, a la medida de tu día.", "prompt_text": "¿Cuál es la versión más corta de tu pausa, para las comidas con prisa?", "gesture": "Prueba tu versión de emergencia en una comida con prisa.", "take_away": "Incluso una sola respiración te devuelve a ti."}, "ru": {"title": "Твоя запасная версия", "idea": "Некоторые приёмы пищи проходят на бегу: в офисе, в машине, между двумя встречами. В такие дни полная пауза кажется невозможной.\n\nПридумай крошечную версию: один вдох перед первым кусочком или просто вопрос себе «насколько я сейчас голодна?». Это сохраняет связь с телом даже в шуме.\n\nЭто не значит делать хуже. Это значит оставаться внимательной — в меру своего дня.", "prompt_text": "Какая самая короткая версия твоей паузы — для еды впопыхах?", "gesture": "Попробуй запасную версию, когда ешь впопыхах.", "take_away": "Даже один вдох возвращает тебя к себе."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'ecouter-sa-faim'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 6);

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 7, 'journal_prompt', $q$Ta marque de satisfaction$q$, $q$Comment vas-tu marquer la fin d'un repas, pour te dire que c'était bon ?$q$, 'ancrer', $q$Manger peut aussi être un moment de plaisir, et le plaisir aide à sentir que c'est assez. Terminer un repas en le remarquant, c'est le refermer doucement.

Ta marque peut être un « merci » silencieux, une main posée sur le ventre, quelques secondes à savourer la dernière bouchée. Quelque chose de simple, qui te ressemble.

Avec ta pause, ta version de secours et cette marque, tu as un rituel qui t'appartient. Le parcours se termine ; l'écoute, elle, continue.$q$, $q$À la fin d'un repas, offre-toi ta marque de satisfaction.$q$, $q$Savourer, c'est aussi écouter.$q$, 7, 0, $q${"en": {"title": "Your mark of satisfaction", "idea": "Eating can also be a moment of pleasure, and pleasure helps you feel when it's enough. Ending a meal by noticing it is closing it gently.\n\nYour mark can be a silent \"thank you\", a hand on your belly, a few seconds savouring the last bite. Something simple that feels like you.\n\nWith your pause, your backup version and this mark, you have a ritual that belongs to you. The journey ends; the listening carries on.", "prompt_text": "How will you mark the end of a meal, to tell yourself it was good?", "gesture": "At the end of a meal, give yourself your mark of satisfaction.", "take_away": "Savouring is listening too."}, "he": {"title": "סימן הסיפוק שלך", "idea": "אכילה יכולה להיות גם רגע של הנאה, וההנאה עוזרת להרגיש מתי זה מספיק. לסיים ארוחה תוך שימת לב אליה זה לסגור אותה בעדינות.\n\nהסימן שלך יכול להיות \"תודה\" שקטה, יד מונחת על הבטן, כמה שניות להתענג על הביס האחרון. משהו פשוט, שדומה לך.\n\nעם ההפסקה שלך, גרסת הגיבוי והסימן הזה, יש לך טקס ששייך לך. המסלול מסתיים; ההקשבה ממשיכה.", "prompt_text": "איך תסמני את סוף הארוחה, כדי לומר לעצמך שהיה טוב?", "gesture": "בסוף ארוחה, העניקי לעצמך את סימן הסיפוק שלך.", "take_away": "להתענג זה גם להקשיב."}, "es": {"title": "Tu señal de satisfacción", "idea": "Comer también puede ser un momento de placer, y el placer ayuda a sentir cuándo es suficiente. Terminar una comida dándote cuenta de ella es cerrarla con suavidad.\n\nTu señal puede ser un «gracias» silencioso, una mano sobre el vientre, unos segundos para saborear el último bocado. Algo sencillo, que se parece a ti.\n\nCon tu pausa, tu versión de emergencia y esta señal, tienes un ritual que te pertenece. El recorrido termina; la escucha continúa.", "prompt_text": "¿Cómo vas a marcar el final de una comida, para decirte que estuvo bien?", "gesture": "Al final de una comida, regálate tu señal de satisfacción.", "take_away": "Saborear también es escuchar."}, "ru": {"title": "Твой знак удовлетворения", "idea": "Еда может быть и моментом удовольствия, а удовольствие помогает почувствовать, что достаточно. Закончить приём пищи, заметив его, — значит мягко его завершить.\n\nТвоим знаком может стать безмолвное «спасибо», ладонь на животе, несколько секунд, чтобы насладиться последним кусочком. Что-то простое, похожее на тебя.\n\nС паузой, запасной версией и этим знаком у тебя есть ритуал, который принадлежит тебе. Путь заканчивается, а умение слушать остаётся.", "prompt_text": "Как ты отметишь окончание еды, чтобы сказать себе, что было хорошо?", "gesture": "В конце еды подари себе свой знак удовлетворения.", "take_away": "Наслаждаться — это тоже слушать."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'ecouter-sa-faim'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 7);

insert into public.mindset_programs (slug, title, subtitle, description, for_you_if, minutes_range, day_count, sort_order, i18n)
  select 'sortir-du-tout-ou-rien', $q$Sortir du tout ou rien$q$, $q$Faire un peu, souvent, plutôt que tout, parfois.$q$, $q$Sept jours pour trouver l'entre-deux, là où les gestes tiennent vraiment.$q$, $q$Tu as tendance à tout lâcher dès qu'une journée ne se passe pas comme prévu, tu te dis souvent « tant pis, je recommencerai lundi », ou tu as envie de plus de douceur avec toi-même.$q$, $q$5 à 10 min$q$, 7, 5, $q${"en": {"title": "Step out of all or nothing", "subtitle": "Do a little, often, rather than everything, sometimes.", "description": "Seven days to find the in-between, where gestures really hold.", "for_you_if": "You tend to drop everything as soon as a day doesn't go as planned, you often tell yourself \"oh well, I'll start again on Monday\", or you'd like more gentleness with yourself.", "minutes_range": "5–10 min"}, "he": {"title": "לצאת מהכול או כלום", "subtitle": "לעשות קצת, לעיתים קרובות, במקום הכול, לפעמים.", "description": "שבעה ימים למצוא את האמצע, המקום שבו המחוות באמת מחזיקות.", "for_you_if": "את נוטה לוותר על הכול ברגע שיום לא הולך כמתוכנן, את אומרת לעצמך הרבה \"לא נורא, אתחיל מחדש ביום שני\", או שמתחשק לך יותר רכות כלפי עצמך.", "minutes_range": "5–10 דק׳"}, "es": {"title": "Salir del todo o nada", "subtitle": "Hacer un poco, a menudo, en lugar de todo, a veces.", "description": "Siete días para encontrar el término medio, donde los gestos se sostienen de verdad.", "for_you_if": "Tiendes a dejarlo todo en cuanto un día no sale como estaba previsto, te dices a menudo «da igual, empiezo otra vez el lunes», o te apetece más suavidad contigo misma.", "minutes_range": "5 a 10 min"}, "ru": {"title": "Выйти из «всё или ничего»", "subtitle": "Делать понемногу и часто, а не всё и иногда.", "description": "Семь дней, чтобы найти середину — там, где действия действительно держатся.", "for_you_if": "Ты склонна всё бросать, как только день идёт не по плану; часто говоришь себе «ладно, начну заново с понедельника»; или тебе хочется больше мягкости к себе.", "minutes_range": "5–10 мин"}}$q$::jsonb
  where not exists (select 1 from public.mindset_programs where slug = 'sortir-du-tout-ou-rien');

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 1, 'journal_prompt', $q$Le piège du parfait$q$, $q$Quelle phrase de « tout ou rien » te dis-tu le plus souvent ?$q$, 'comprendre', $q$« Si je ne peux pas faire la séance entière, je ne fais rien. » « J'ai craqué ce midi, la journée est fichue. » Ces phrases te parlent peut-être. C'est la pensée du tout ou rien.

Elle part souvent d'une belle intention : bien faire. Mais elle laisse peu de place à la vraie vie, avec ses imprévus et ses jours fatigués.

Aujourd'hui, remarque simplement quand cette petite voix se fait entendre. Pas besoin de la faire taire : juste la reconnaître.$q$, $q$Quand tu entends cette phrase, dis-toi simplement : « je la remarque ».$q$, $q$Ce n'est pas tout ou rien. C'est toi, tous les jours.$q$, 5, 0, $q${"en": {"title": "The perfection trap", "idea": "\"If I can't do the whole session, I won't do anything.\" \"I gave in at lunch, the day is ruined.\" Maybe these phrases sound familiar. That's all-or-nothing thinking.\n\nIt often comes from a lovely intention: doing things well. But it leaves little room for real life, with its surprises and its tired days.\n\nToday, simply notice when this little voice speaks up. No need to silence it: just recognise it.", "prompt_text": "Which all-or-nothing phrase do you tell yourself most often?", "gesture": "When you hear that phrase, simply tell yourself: \"I notice it.\"", "take_away": "It isn't all or nothing. It's you, every day."}, "he": {"title": "המלכודת של המושלם", "idea": "\"אם אני לא יכולה לעשות את האימון כולו, אני לא עושה כלום.\" \"נשברתי בצהריים, היום הלך.\" אולי המשפטים האלה מוכרים לך. זו החשיבה של הכול או כלום.\n\nהיא נובעת לעיתים קרובות מכוונה יפה: לעשות טוב. אבל היא משאירה מעט מקום לחיים האמיתיים, עם ההפתעות והימים העייפים שלהם.\n\nהיום פשוט שימי לב מתי הקול הקטן הזה נשמע. אין צורך להשתיק אותו: רק לזהות אותו.", "prompt_text": "איזה משפט של \"הכול או כלום\" את אומרת לעצמך הכי הרבה?", "gesture": "כשאת שומעת את המשפט הזה, פשוט אמרי לעצמך: \"אני שמה לב אליו\".", "take_away": "זה לא הכול או כלום. זו את, כל יום."}, "es": {"title": "La trampa de lo perfecto", "idea": "«Si no puedo hacer la sesión entera, no hago nada.» «He caído a mediodía, el día está perdido.» Quizá estas frases te suenen. Es el pensamiento de todo o nada.\n\nA menudo nace de una bonita intención: hacerlo bien. Pero deja poco sitio a la vida real, con sus imprevistos y sus días cansados.\n\nHoy, simplemente fíjate en cuándo se hace oír esa vocecita. No hace falta callarla: solo reconocerla.", "prompt_text": "¿Qué frase de «todo o nada» te dices más a menudo?", "gesture": "Cuando oigas esa frase, dite simplemente: «me doy cuenta».", "take_away": "No es todo o nada. Eres tú, cada día."}, "ru": {"title": "Ловушка идеального", "idea": "«Если не могу сделать всю тренировку, не делаю ничего.» «Сорвалась в обед — день пропал.» Возможно, эти фразы тебе знакомы. Это мышление «всё или ничего».\n\nЧасто оно рождается из хорошего намерения — сделать всё как следует. Но оставляет мало места настоящей жизни с её неожиданностями и усталыми днями.\n\nСегодня просто замечай, когда звучит этот голосок. Не нужно заставлять его замолчать — достаточно узнать его.", "prompt_text": "Какую фразу в духе «всё или ничего» ты говоришь себе чаще всего?", "gesture": "Когда слышишь эту фразу, просто скажи себе: «я её замечаю».", "take_away": "Это не «всё или ничего». Это ты, каждый день."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'sortir-du-tout-ou-rien'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 1);

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 2, 'journal_prompt', $q$Ce que coûte le tout$q$, $q$Repense à une fois où tu as tout lâché d'un coup. Qu'aurais-tu aimé te dire ?$q$, 'comprendre', $q$Viser le tout demande une énergie énorme. Les premiers jours, ça porte. Puis la fatigue arrive, un imprévu, et tout s'arrête d'un coup.

Ce n'est pas un manque de volonté. C'est que le tout n'est pas fait pour durer. Le corps et la tête ont besoin de rythmes qu'on peut tenir les jours ordinaires.

Repense à une période où tu as tout donné, puis tout lâché. Qu'aurais-tu aimé te dire à ce moment-là ?$q$, $q$Fais une chose aujourd'hui à moitié, volontairement, et remarque ce que ça fait.$q$, $q$Ce qui dure, c'est ce qu'on peut tenir les jours ordinaires.$q$, 6, 0, $q${"en": {"title": "What \"everything\" costs", "idea": "Aiming for everything takes enormous energy. The first few days, it carries you. Then tiredness comes, something unexpected, and it all stops at once.\n\nIt isn't a lack of willpower. It's that \"everything\" isn't made to last. Body and mind need rhythms you can keep on ordinary days.\n\nThink back to a time when you gave everything, then dropped everything. What would you have liked to tell yourself then?", "prompt_text": "Think back to a time you dropped everything at once. What would you have liked to tell yourself?", "gesture": "Do one thing halfway today, on purpose, and notice how it feels.", "take_away": "What lasts is what you can keep on ordinary days."}, "he": {"title": "מה עולה ה\"הכול\"", "idea": "לשאוף להכול דורש אנרגיה עצומה. בימים הראשונים זה נושא אותך. ואז מגיעה עייפות, משהו לא צפוי, והכול נעצר בבת אחת.\n\nזה לא חוסר כוח רצון. פשוט ה\"הכול\" לא נועד להחזיק. הגוף והראש צריכים קצבים שאפשר לשמור עליהם בימים רגילים.\n\nחשבי על תקופה שבה נתת הכול, ואז ויתרת על הכול. מה היית רוצה לומר לעצמך באותו רגע?", "prompt_text": "חשבי על פעם שבה ויתרת על הכול בבת אחת. מה היית רוצה לומר לעצמך?", "gesture": "עשי היום דבר אחד בחצי, בכוונה, ושימי לב איך זה מרגיש.", "take_away": "מה שמחזיק הוא מה שאפשר לשמור עליו בימים רגילים."}, "es": {"title": "Lo que cuesta el todo", "idea": "Aspirar al todo exige una energía enorme. Los primeros días te lleva. Luego llega el cansancio, un imprevisto, y todo se para de golpe.\n\nNo es falta de voluntad. Es que el todo no está hecho para durar. El cuerpo y la cabeza necesitan ritmos que se puedan mantener los días normales.\n\nPiensa en una época en que lo diste todo y luego lo dejaste todo. ¿Qué te habría gustado decirte en ese momento?", "prompt_text": "Piensa en una vez en que lo dejaste todo de golpe. ¿Qué te habría gustado decirte?", "gesture": "Haz hoy una cosa a medias, a propósito, y fíjate en lo que sientes.", "take_away": "Lo que dura es lo que se puede mantener los días normales."}, "ru": {"title": "Чего стоит «всё»", "idea": "Стремление ко «всему» требует огромной энергии. Первые дни это несёт. Потом приходит усталость, что-то неожиданное — и всё разом останавливается.\n\nЭто не недостаток силы воли. Просто «всё» не рассчитано надолго. Телу и голове нужны ритмы, которые можно держать в обычные дни.\n\nВспомни период, когда ты отдавала всё, а потом всё бросила. Что тебе хотелось бы тогда себе сказать?", "prompt_text": "Вспомни случай, когда ты разом всё бросила. Что тебе хотелось бы себе сказать?", "gesture": "Сделай сегодня что-то наполовину, нарочно, и заметь, каково это.", "take_away": "Долго держится то, что можно делать в обычные дни."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'sortir-du-tout-ou-rien'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 2);

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 3, 'journal_prompt', $q$La version entre-deux$q$, $q$Dans quel domaine as-tu tendance au tout ou rien ? Quelle serait sa version entre-deux ?$q$, 'essayer', $q$Entre tout et rien, il y a une infinité de possibilités. Dix minutes de marche au lieu d'une heure. Un légume ajouté plutôt qu'un repas parfait. Cinq étirements au lieu d'une séance.

Ces versions entre-deux ne sont pas des consolations. Ce sont elles qui construisent, jour après jour, une vraie régularité.

Choisis un domaine où tu as tendance au tout ou rien, et imagine sa version entre-deux : pas la meilleure, celle que tu peux faire.$q$, $q$Fais la version entre-deux d'une chose que tu aurais laissée tomber.$q$, $q$Un peu, c'est déjà beaucoup.$q$, 6, 0, $q${"en": {"title": "The in-between version", "idea": "Between everything and nothing there are endless possibilities. Ten minutes of walking instead of an hour. One added vegetable rather than a perfect meal. Five stretches instead of a full session.\n\nThese in-between versions aren't consolations. They're what builds, day after day, real regularity.\n\nChoose an area where you tend towards all or nothing, and imagine its in-between version: not the best one, the one you can do.", "prompt_text": "In which area do you tend towards all or nothing? What would its in-between version be?", "gesture": "Do the in-between version of something you would have dropped.", "take_away": "A little is already a lot."}, "he": {"title": "גרסת האמצע", "idea": "בין הכול לכלום יש אינסוף אפשרויות. עשר דקות הליכה במקום שעה. ירק אחד שנוסף במקום ארוחה מושלמת. חמש מתיחות במקום אימון שלם.\n\nגרסאות האמצע האלה אינן נחמה. הן אלה שבונות, יום אחרי יום, קביעות אמיתית.\n\nבחרי תחום שבו את נוטה להכול או כלום, ודמייני את גרסת האמצע שלו: לא הטובה ביותר, זו שאת יכולה לעשות.", "prompt_text": "באיזה תחום את נוטה להכול או כלום? מה תהיה גרסת האמצע שלו?", "gesture": "עשי את גרסת האמצע של משהו שהיית מוותרת עליו.", "take_away": "קצת זה כבר הרבה."}, "es": {"title": "La versión intermedia", "idea": "Entre todo y nada hay infinitas posibilidades. Diez minutos de paseo en lugar de una hora. Una verdura añadida en lugar de una comida perfecta. Cinco estiramientos en lugar de una sesión.\n\nEstas versiones intermedias no son consuelos. Son ellas las que construyen, día tras día, una verdadera regularidad.\n\nElige un ámbito en el que tiendas al todo o nada e imagina su versión intermedia: no la mejor, la que puedes hacer.", "prompt_text": "¿En qué ámbito tiendes al todo o nada? ¿Cuál sería su versión intermedia?", "gesture": "Haz la versión intermedia de algo que habrías dejado caer.", "take_away": "Un poco ya es mucho."}, "ru": {"title": "Версия посередине", "idea": "Между «всем» и «ничем» — бесконечно много вариантов. Десять минут прогулки вместо часа. Один добавленный овощ вместо идеального обеда. Пять растяжек вместо целой тренировки.\n\nЭти промежуточные версии — не утешение. Именно они день за днём создают настоящую регулярность.\n\nВыбери область, где ты склонна к «всё или ничего», и представь её промежуточную версию: не лучшую, а ту, что тебе по силам.", "prompt_text": "В какой области ты склонна к «всё или ничего»? Какой была бы её промежуточная версия?", "gesture": "Сделай промежуточную версию того, что ты бы бросила.", "take_away": "Немного — это уже много."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'sortir-du-tout-ou-rien'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 3);

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 4, 'journal_prompt', $q$Accrocher ton entre-deux$q$, $q$Écris ta phrase d'ancrage : « Après…, je… »$q$, 'essayer', $q$Pour que ta version entre-deux devienne naturelle, accroche-la à un moment qui revient chaque jour. Ainsi, elle ne dépend plus de ton humeur ou de ton énergie du moment.

« Après avoir déposé les enfants, je marche dix minutes. » « Après avoir fermé mon ordinateur, je m'étire cinq minutes. » Une phrase simple, un moment précis.

Choisis un ancrage solide, et place ton geste juste après. Le jour où tout déborde, c'est ce lien qui te portera.$q$, $q$Fais ton geste entre-deux juste après ton ancrage.$q$, $q$Un moment précis vaut mieux qu'une grande promesse.$q$, 6, 0, $q${"en": {"title": "Anchor your in-between", "idea": "For your in-between version to become natural, hook it onto a moment that comes back every day. That way it no longer depends on your mood or your energy of the moment.\n\n\"After I drop the kids off, I walk for ten minutes.\" \"After I close my laptop, I stretch for five minutes.\" One simple sentence, one precise moment.\n\nChoose a solid anchor and place your gesture right after it. On the day everything overflows, this link is what will carry you.", "prompt_text": "Write your anchor sentence: \"After…, I…\"", "gesture": "Do your in-between gesture right after your anchor.", "take_away": "A precise moment is worth more than a big promise."}, "he": {"title": "לעגן את האמצע שלך", "idea": "כדי שגרסת האמצע שלך תהפוך לטבעית, עגני אותה ברגע שחוזר כל יום. כך היא כבר לא תלויה במצב הרוח או באנרגיה של הרגע.\n\n\"אחרי שאני מורידה את הילדים, אני הולכת עשר דקות.\" \"אחרי שאני סוגרת את המחשב, אני מתמתחת חמש דקות.\" משפט פשוט, רגע מדויק.\n\nבחרי עוגן יציב, ומקמי את המחווה מיד אחריו. ביום שבו הכול גולש, הקשר הזה הוא שיישא אותך.", "prompt_text": "כתבי את משפט העוגן שלך: \"אחרי…, אני…\"", "gesture": "עשי את מחוות האמצע שלך מיד אחרי העוגן.", "take_away": "רגע מדויק שווה יותר מהבטחה גדולה."}, "es": {"title": "Anclar tu término medio", "idea": "Para que tu versión intermedia se vuelva natural, engánchala a un momento que se repita cada día. Así ya no depende de tu humor ni de tu energía del momento.\n\n«Después de dejar a los niños, camino diez minutos.» «Después de cerrar el ordenador, me estiro cinco minutos.» Una frase sencilla, un momento preciso.\n\nElige un ancla sólida y coloca tu gesto justo después. El día en que todo se desborde, será ese vínculo el que te sostenga.", "prompt_text": "Escribe tu frase de anclaje: «Después de…, yo…»", "gesture": "Haz tu gesto intermedio justo después de tu ancla.", "take_away": "Un momento preciso vale más que una gran promesa."}, "ru": {"title": "Привязать свою середину", "idea": "Чтобы промежуточная версия стала естественной, привяжи её к моменту, который повторяется каждый день. Тогда она больше не зависит от настроения или сил в данный момент.\n\n«После того как отвожу детей, я гуляю десять минут.» «После того как закрываю ноутбук, я тянусь пять минут.» Простая фраза, точный момент.\n\nВыбери надёжную опору и поставь действие сразу после неё. В день, когда всё через край, тебя понесёт именно эта связь.", "prompt_text": "Напиши свою фразу-опору: «После того как…, я…»", "gesture": "Сделай своё промежуточное действие сразу после опоры.", "take_away": "Точный момент ценнее большого обещания."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'sortir-du-tout-ou-rien'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 4);

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 5, 'journal_prompt', $q$Après un écart$q$, $q$La prochaine fois que tu te diras « c'est fichu », que pourrais-tu te répondre ?$q$, 'essayer', $q$Il y aura des jours où les choses ne se passeront pas comme prévu. Un repas qui déborde, une séance sautée. La pensée du tout ou rien dira : « c'est fichu ».

Tu peux lui répondre autrement : « le prochain geste compte ». Pas demain, pas lundi : le prochain repas, la prochaine heure, la prochaine occasion.

Revenir vite, sans te punir et sans compenser, c'est ce qui casse le cercle. Un écart reste un moment, pas une journée entière.$q$, $q$Après un moment qui ne s'est pas passé comme prévu, choisis simplement le prochain geste.$q$, $q$Le prochain geste compte. Toujours.$q$, 7, 0, $q${"en": {"title": "After a slip", "idea": "There will be days when things don't go as planned. A meal that overflows, a skipped session. All-or-nothing thinking will say: \"it's ruined\".\n\nYou can answer differently: \"the next gesture counts\". Not tomorrow, not Monday: the next meal, the next hour, the next chance.\n\nComing back quickly, without punishing yourself and without making up for it, is what breaks the circle. A slip is a moment, not a whole day.", "prompt_text": "Next time you tell yourself \"it's ruined\", what could you answer?", "gesture": "After a moment that didn't go as planned, simply choose the next gesture.", "take_away": "The next gesture counts. Always."}, "he": {"title": "אחרי סטייה", "idea": "יהיו ימים שבהם הדברים לא ילכו כמתוכנן. ארוחה שגולשת, אימון שדילגת עליו. החשיבה של הכול או כלום תגיד: \"הלך\".\n\nאת יכולה לענות לה אחרת: \"המחווה הבאה חשובה\". לא מחר, לא ביום שני: הארוחה הבאה, השעה הבאה, ההזדמנות הבאה.\n\nלחזור מהר, בלי להעניש את עצמך ובלי לפצות, זה מה ששובר את המעגל. סטייה היא רגע, לא יום שלם.", "prompt_text": "בפעם הבאה שתאמרי לעצמך \"הלך\", מה תוכלי לענות?", "gesture": "אחרי רגע שלא הלך כמתוכנן, פשוט בחרי את המחווה הבאה.", "take_away": "המחווה הבאה חשובה. תמיד."}, "es": {"title": "Después de un desliz", "idea": "Habrá días en que las cosas no salgan como estaba previsto. Una comida que se desborda, una sesión que te saltas. El pensamiento de todo o nada dirá: «se acabó».\n\nPuedes responderle de otra manera: «el próximo gesto cuenta». No mañana, no el lunes: la próxima comida, la próxima hora, la próxima ocasión.\n\nVolver rápido, sin castigarte y sin compensar, es lo que rompe el círculo. Un desliz es un momento, no un día entero.", "prompt_text": "La próxima vez que te digas «se acabó», ¿qué podrías responderte?", "gesture": "Después de un momento que no salió como estaba previsto, elige simplemente el próximo gesto.", "take_away": "El próximo gesto cuenta. Siempre."}, "ru": {"title": "После срыва", "idea": "Будут дни, когда всё пойдёт не по плану. Обед, который вышел за рамки, пропущенная тренировка. Мышление «всё или ничего» скажет: «всё пропало».\n\nМожно ответить ему иначе: «важно следующее действие». Не завтра, не в понедельник: следующая еда, следующий час, следующая возможность.\n\nВернуться быстро, не наказывая себя и ничего не компенсируя, — вот что разрывает круг. Срыв — это момент, а не целый день.", "prompt_text": "Когда в следующий раз скажешь себе «всё пропало», что ты могла бы ответить?", "gesture": "После момента, который пошёл не по плану, просто выбери следующее действие.", "take_away": "Следующее действие важно. Всегда."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'sortir-du-tout-ou-rien'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 5);

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 6, 'journal_prompt', $q$Ta version de secours$q$, $q$Quelle est ta version d'une minute, pour les jours où même l'entre-deux paraît trop ?$q$, 'ancrer', $q$Même la version entre-deux peut sembler trop, certains jours. Prévois alors une version encore plus petite : celle qui tient en une minute.

Une minute de marche, une seule respiration profonde, un verre d'eau. Ce n'est pas rien : c'est garder le lien, et refuser le « rien ».

Écris-la maintenant, à tête reposée. Les jours difficiles, tu n'auras pas à réfléchir : elle sera déjà là.$q$, $q$Essaie ta version d'une minute, juste pour la connaître.$q$, $q$Le rien n'existe plus quand une minute suffit.$q$, 6, 0, $q${"en": {"title": "Your backup version", "idea": "Even the in-between version can feel like too much on some days. So plan an even smaller version: one that fits into a minute.\n\nOne minute of walking, a single deep breath, a glass of water. It isn't nothing: it's keeping the link, and refusing the \"nothing\".\n\nWrite it now, with a clear head. On hard days you won't have to think: it will already be there.", "prompt_text": "What's your one-minute version, for days when even the in-between feels like too much?", "gesture": "Try your one-minute version, just to get to know it.", "take_away": "\"Nothing\" no longer exists when one minute is enough."}, "he": {"title": "גרסת הגיבוי שלך", "idea": "בימים מסוימים, אפילו גרסת האמצע יכולה להיראות יותר מדי. אז הכיני גרסה קטנה עוד יותר: כזו שנכנסת בדקה אחת.\n\nדקה של הליכה, נשימה עמוקה אחת, כוס מים. זה לא כלום: זה לשמור על הקשר, ולסרב ל\"כלום\".\n\nכתבי אותה עכשיו, בראש שקט. בימים הקשים לא תצטרכי לחשוב: היא כבר תהיה שם.", "prompt_text": "מהי גרסת הדקה האחת שלך, לימים שבהם אפילו האמצע נראה יותר מדי?", "gesture": "נסי את גרסת הדקה האחת שלך, רק כדי להכיר אותה.", "take_away": "ה\"כלום\" כבר לא קיים כשדקה אחת מספיקה."}, "es": {"title": "Tu versión de emergencia", "idea": "Algunos días, incluso la versión intermedia puede parecer demasiado. Prevé entonces una versión todavía más pequeña: la que cabe en un minuto.\n\nUn minuto de paseo, una sola respiración profunda, un vaso de agua. No es nada: es mantener el vínculo y rechazar el «nada».\n\nEscríbela ahora, con la cabeza tranquila. Los días difíciles no tendrás que pensar: ya estará ahí.", "prompt_text": "¿Cuál es tu versión de un minuto, para los días en que incluso el término medio parece demasiado?", "gesture": "Prueba tu versión de un minuto, solo para conocerla.", "take_away": "La nada deja de existir cuando basta un minuto."}, "ru": {"title": "Твоя запасная версия", "idea": "В некоторые дни даже промежуточная версия может казаться слишком большой. Тогда придумай ещё меньшую — ту, что укладывается в одну минуту.\n\nМинута ходьбы, один глубокий вдох, стакан воды. Это не ничто: это сохранить связь и отказаться от «ничего».\n\nЗапиши её сейчас, на свежую голову. В трудные дни не придётся думать: она уже будет готова.", "prompt_text": "Какая у тебя версия на одну минуту — для дней, когда даже середина кажется слишком большой?", "gesture": "Попробуй свою версию на одну минуту, просто чтобы с ней познакомиться.", "take_away": "«Ничего» больше нет, когда достаточно одной минуты."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'sortir-du-tout-ou-rien'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 6);

insert into public.mindset_program_steps (program_id, day_number, kind, title, prompt_text, phase, idea, gesture, take_away, minutes, sort_order, i18n)
  select p.id, 7, 'journal_prompt', $q$Ta marque de satisfaction$q$, $q$Comment vas-tu remarquer ton geste, une fois fait ?$q$, 'ancrer', $q$Le tout ou rien oublie souvent de remarquer ce qui a été fait. Pourtant, reconnaître un petit geste, c'est ce qui donne envie d'y revenir.

Ta marque peut être un « c'est fait » à voix basse, une respiration, un instant à regarder par la fenêtre. Une façon simple de te dire que ça compte.

Avec ton ancrage, ta version de secours et cette marque, tu as un geste qui tient même les jours imparfaits. Le parcours se termine ; l'entre-deux, lui, reste.$q$, $q$Après ton geste, offre-toi ta marque de satisfaction.$q$, $q$Ce que tu fais compte, même quand c'est petit.$q$, 7, 0, $q${"en": {"title": "Your mark of satisfaction", "idea": "All or nothing often forgets to notice what has been done. Yet acknowledging a small gesture is what makes you want to come back to it.\n\nYour mark can be a quiet \"done\", a breath, a moment looking out of the window. A simple way of telling yourself it counts.\n\nWith your anchor, your backup version and this mark, you have a gesture that holds even on imperfect days. The journey ends; the in-between stays.", "prompt_text": "How will you notice your gesture, once it's done?", "gesture": "After your gesture, give yourself your mark of satisfaction.", "take_away": "What you do counts, even when it's small."}, "he": {"title": "סימן הסיפוק שלך", "idea": "ה\"הכול או כלום\" שוכח לעיתים קרובות לשים לב למה שנעשה. ובכל זאת, להכיר במחווה קטנה זה מה שגורם לרצות לחזור אליה.\n\nהסימן שלך יכול להיות \"זהו, עשיתי\" בשקט, נשימה, רגע של הסתכלות מהחלון. דרך פשוטה לומר לעצמך שזה נחשב.\n\nעם העוגן שלך, גרסת הגיבוי והסימן הזה, יש לך מחווה שמחזיקה גם בימים לא מושלמים. המסלול מסתיים; האמצע נשאר.", "prompt_text": "איך תשימי לב למחווה שלך, אחרי שעשית אותה?", "gesture": "אחרי המחווה שלך, העניקי לעצמך את סימן הסיפוק שלך.", "take_away": "מה שאת עושה נחשב, גם כשזה קטן."}, "es": {"title": "Tu señal de satisfacción", "idea": "El todo o nada a menudo olvida fijarse en lo que se ha hecho. Sin embargo, reconocer un pequeño gesto es lo que da ganas de volver a él.\n\nTu señal puede ser un «hecho» en voz baja, una respiración, un instante mirando por la ventana. Una forma sencilla de decirte que cuenta.\n\nCon tu ancla, tu versión de emergencia y esta señal, tienes un gesto que se sostiene incluso los días imperfectos. El recorrido termina; el término medio se queda.", "prompt_text": "¿Cómo vas a fijarte en tu gesto, una vez hecho?", "gesture": "Después de tu gesto, regálate tu señal de satisfacción.", "take_away": "Lo que haces cuenta, aunque sea pequeño."}, "ru": {"title": "Твой знак удовлетворения", "idea": "«Всё или ничего» часто забывает замечать то, что уже сделано. А ведь признать маленькое действие — значит захотеть к нему вернуться.\n\nТвоим знаком может быть тихое «готово», вдох, мгновение у окна. Простой способ сказать себе, что это важно.\n\nС опорой, запасной версией и этим знаком у тебя есть действие, которое держится даже в неидеальные дни. Путь заканчивается, а середина остаётся.", "prompt_text": "Как ты отметишь своё действие, когда оно сделано?", "gesture": "После своего действия подари себе свой знак удовлетворения.", "take_away": "То, что ты делаешь, важно, даже если это мало."}}$q$::jsonb
  from public.mindset_programs p where p.slug = 'sortir-du-tout-ou-rien'
  and not exists (select 1 from public.mindset_program_steps s where s.program_id = p.id and s.day_number = 7);
